//! Schema of the bulk native track tool.
use super::ToolSchema;

/// Most tracks one `native_timeline_tracks_set` call may carry.
pub(crate) const MAX_TRACKS: usize = 256;

pub(crate) const NATIVE_BULK_TOOLS: &[ToolSchema] = &[
    CAMERA,
    ToolSchema {
        name: "native_timeline_tracks_set",
        description: "Create 1-256 property tracks with all their keys in ONE undoable, all-or-nothing edit; far faster than one native_timeline_add_property_track call or batch entry per track (a 200 track, 3000 key scene flushes in well under a second). tracks is an array; each entry has the arguments of native_timeline_add_property_track without documentId: trackId, targetId, property, valueType, interpolation, value (the tick-zero value), optional name, optional noise (as in native_timeline_add_property_track) and optional keys [{tick, value, ease?}] (ease: same names, bezier:x1,y1,x2,y2 string or [x1,y1,x2,y2] array as native_timeline_set_property_key; interp is an alias) (at most 256 per track, 16384 per call; same value forms and interp names). The whole request is limited to 2 MiB and 65536 JSON tokens, so split a very large scene over several calls (a trs key given as a 7-number array costs fewer tokens than an object). Counts as 1 + tracks/8 requests of the per-minute budget. Any rejected track (bad id, unknown target, duplicate trackId, tick past the end, mismatched value) names its index as `tracks[i]` and nothing changes. Example: {\"tracks\":[{\"trackId\":\"fade\",\"targetId\":\"vexel-object-1\",\"property\":\"opacity\",\"valueType\":\"scalar\",\"interpolation\":\"linear\",\"value\":0,\"keys\":[{\"tick\":12,\"value\":1}]}]}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"tracks\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":256,\"items\":{\"type\":\"object\",\"properties\":{\"trackId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"targetId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256},\"property\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"valueType\":{\"type\":\"string\",\"enum\":[\"scalar\",\"rgba\",\"transform2d\",\"trs\",\"boolean\",\"path\"]},\"interpolation\":{\"type\":\"string\",\"enum\":[\"step\",\"linear\",\"cubic\"]},\"value\":{\"type\":[\"number\",\"boolean\",\"array\",\"object\",\"string\"]},\"name\":{\"type\":\"string\",\"maxLength\":256},\"noise\":{\"type\":\"object\",\"properties\":{\"amplitude\":{\"type\":\"number\",\"minimum\":0,\"maximum\":100000},\"frequency\":{\"type\":\"number\",\"exclusiveMinimum\":0,\"maximum\":240},\"seed\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":4294967295},\"octaves\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":4}},\"required\":[\"amplitude\"],\"additionalProperties\":false},\"keys\":{\"type\":\"array\",\"maxItems\":256,\"items\":{\"type\":\"object\",\"properties\":{\"tick\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":4294967295},\"value\":{\"type\":[\"number\",\"boolean\",\"array\",\"object\",\"string\"]},\"ease\":{\"type\":[\"string\",\"array\"]},\"interp\":{\"type\":\"string\"}},\"required\":[\"tick\",\"value\"],\"additionalProperties\":false}}},\"required\":[\"trackId\",\"targetId\",\"property\",\"valueType\",\"interpolation\",\"value\"],\"additionalProperties\":false}}}",
        required: "documentId,tracks",
        fields: "documentId:string;tracks:array",
    },
];

const CAMERA: ToolSchema = ToolSchema {
    name: "native_timeline_set_camera",
    description: "Set (replace) or clear the camera in ONE undoable edit: a view transform applied at render time to preview, render_png and exports, with no wrapper group. The camera looks at the viewBox centre displaced by x,y (user units), scaled by zoom (1 = none) and rolled by rotate degrees. keys: at most 256 of {tick, x?, y?, zoom?, rotate?, ease?}; each channel interpolates between the keys that name it (ease as in native_timeline_set_property_key, shaping the segment after the key; unkeyed channels hold identity). shake: {amplitude (pixels), frequency? (Hz, default 4), seed?, octaves? (1-4), rotate? (degrees of roll)} adds deterministic handheld shake. clear:true removes the camera. Example: {\"keys\":[{\"tick\":0,\"zoom\":1},{\"tick\":48,\"zoom\":1.6,\"x\":40,\"ease\":\"ease_in_out_cubic\"}],\"shake\":{\"amplitude\":3,\"seed\":7}}.",
    properties: "{\"documentId\":{\"type\":\"string\"},\"keys\":{\"type\":\"array\",\"maxItems\":256,\"items\":{\"type\":\"object\",\"properties\":{\"tick\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":4294967295},\"x\":{\"type\":\"number\"},\"y\":{\"type\":\"number\"},\"zoom\":{\"type\":\"number\",\"minimum\":0.01,\"maximum\":100},\"rotate\":{\"type\":\"number\"},\"ease\":{\"type\":[\"string\",\"array\"]}},\"required\":[\"tick\"],\"additionalProperties\":false}},\"shake\":{\"type\":\"object\"},\"clear\":{\"type\":\"boolean\"}}",
    required: "documentId",
    fields: "documentId:string;keys:array;shake:object;clear:boolean",
};
